export default function CrudCard({
    title,
    subtitle,
    description,
    ativo,
    onClick,
    actions,
    disabled
}) {
    return (
        <div
            className={`crud-card ${disabled ? 'disabled' : ''}`}
            onClick={!disabled ? onClick : undefined}
        >
            <div
                className="crud-card-content"
                title={!disabled ? "Clique para visualizar detalhes" : ""}
            >
                <strong>{title}</strong>

                {subtitle && (
                    <div className="crud-subtitle">
                        {subtitle}
                    </div>
                )}

                {description && (
                    <div className="crud-description">
                        {description}
                    </div>
                )}
            </div>

            <div
                className="crud-card-actions"
                onClick={e => e.stopPropagation()}
            >
                {actions}
            </div>
        </div>
    )
}

import { useAuth } from '../auth/AuthContext'
import { useLocation, Link } from 'react-router-dom'
import { useState, useRef, useEffect } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import '../styles/layout.css'

export default function Layout({ children }) {
    const { user, logout } = useAuth()
    const location = useLocation()
    const [open, setOpen] = useState(false)
    const menuRef = useRef(null)

    useEffect(() => {
        function handleClickOutside(event) {
            if (menuRef.current && !menuRef.current.contains(event.target)) {
                setOpen(false)
            }
        }
        document.addEventListener('mousedown', handleClickOutside)
        return () => document.removeEventListener('mousedown', handleClickOutside)
    }, [])

    return (
        <div className="app-container">

            <header className="header">
                <strong>CEIFA</strong>

                <div className="header-right" ref={menuRef}>
                    <span
                        className="user-name"
                        onClick={() => setOpen(!open)}
                    >
                        {user?.email} ▾
                    </span>

                    {open && (
                        <div className="user-menu">
                            <Link
                                to="/auth/trocar-senha"
                                className="user-menu-item"
                                onClick={() => setOpen(false)}
                            >
                                Trocar senha
                            </Link>

                            <button
                                onClick={logout}
                                className="user-menu-item"
                            >
                                Sair
                            </button>
                        </div>
                    )}
                </div>
            </header>

            <AnimatePresence mode="wait">
                <motion.main
                    key={location.pathname}
                    className="page-content"
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -12 }}
                    transition={{ duration: 0.25 }}
                >
                    {children}
                </motion.main>
            </AnimatePresence>

            <footer>
                <div>Versão 1.0.0</div>
                <div>Copyright © CEIFA</div>
                <div>{new Date().toLocaleDateString()}</div>
            </footer>
        </div>
    )
}

import { useNavigate } from 'react-router-dom'
import { motion } from 'framer-motion'
import '../styles/pages.css'

export default function PageLayout({
    title,
    showBack = false,
    backTo = null,
    actions = null,
    children
}) {
    const navigate = useNavigate()

    function handleBack() {
        if (backTo) {
            navigate(backTo)
            return
        }
        navigate(-1)
    }

    return (
        <motion.div
            className="page-container"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.25, ease: 'easeOut' }}
        >
            <div className="page-header">
                <div className="header-actions">
                    {showBack && (
                        <button
                            className="back-button"
                            onClick={handleBack}
                        >
                            ← Voltar
                        </button>
                    )}
                    {actions}
                </div>

                <h2>{title}</h2>
            </div>

            {children}
        </motion.div>
    )
}

import { useLocation } from 'react-router-dom'
import { AnimatePresence, motion } from 'framer-motion'

export default function PageTransition({ children }) {
    const location = useLocation()

    return (
        <AnimatePresence mode="wait">
            <motion.div
                key={location.pathname}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.25 }}
            >
                {children}
            </motion.div>
        </AnimatePresence>
    )
}

