import { useState, useEffect } from 'react'
import { NavLink, useNavigate, useLocation } from 'react-router-dom'
import {
    Map,
    Tractor,
    Users,
    DollarSign,
    Package,
    ArrowLeftRight,
    Building2,
    Sprout,
    ChevronLeft,
    ChevronRight,
    ChevronDown,
    X,
    UserCog,
    Home,
    ClipboardList,
    ShoppingCart,
    BarChart3
} from 'lucide-react'
import { useAuth } from '../auth/AuthContext'
import '../styles/layout.css'

export default function Sidebar({
    collapsed,
    toggleCollapse,
    mobileOpen,
    closeMobile
}) {
    const { user, safraAtiva } = useAuth()
    const navigate = useNavigate()
    const location = useLocation()

    const [openFinanceiro, setOpenFinanceiro] = useState(false)
    const [openProdutos, setOpenProdutos] = useState(false)
    const [openTalhoes, setOpenTalhoes] = useState(false)

    /* 🔥 ABRIR SUBMENU AUTOMATICAMENTE */
    // eslint-disable-next-line react-hooks/set-state-in-effect
    useEffect(() => {
        if (location.pathname.startsWith('/contas') || location.pathname.startsWith('/fluxo-caixa')) {
            setOpenFinanceiro(true)
        }

        if (location.pathname.startsWith('/produtos')) {
            setOpenProdutos(true)
        }

        if (location.pathname.startsWith('/talhoes') || location.pathname.startsWith('/safra-talhoes')) {
            setOpenTalhoes(true)
        }
    }, [location.pathname])

    /* 🔥 RESET AO COLAPSAR */
    // eslint-disable-next-line react-hooks/set-state-in-effect
    useEffect(() => {
        if (collapsed) {
            setOpenFinanceiro(false)
            setOpenProdutos(false)
            setOpenTalhoes(false)
        }
    }, [collapsed])

    return (
        <>
            <div
                className={`sidebar-overlay ${mobileOpen ? 'show' : ''}`}
                onClick={closeMobile}
            />

            <aside
                className={`sidebar
                ${collapsed ? 'collapsed' : ''}
                ${mobileOpen ? 'mobile-open' : ''}`}
            >
                <div className="sidebar-top">

                    <div className="sidebar-mobile-header">
                        <button onClick={closeMobile} className="mobile-close-btn">
                            <X size={18} />
                        </button>
                    </div>

                    <div className="sidebar-toggle" onClick={toggleCollapse}>
                        {collapsed ? (
                            <ChevronRight size={18} />
                        ) : (
                            <ChevronLeft size={18} />
                        )}
                    </div>

                </div>

                {!collapsed && (
                    <div className="sidebar-header">
                        {user?.fazendaAtiva?.nome || ''}
                        {safraAtiva && (
                            <div className="sidebar-safra">
                                {safraAtiva.nome}
                            </div>
                        )}
                    </div>
                )}

                <div className="sidebar-context">

                    {user?.perfilId === 2 && (
                        <button
                            className="sidebar-context-button"
                            onClick={() => navigate('/proprietarios')}
                        >
                            <Building2 size={16} />
                            {!collapsed && <span>Trocar Proprietário</span>}
                        </button>
                    )}

                    {(user?.perfilId === 1 || user?.perfilId === 2) && (
                        <button
                            className="sidebar-context-button"
                            onClick={() => navigate('/selecionar-fazenda')}
                        >
                            <Tractor size={16} />
                            {!collapsed && <span>Trocar Fazenda</span>}
                        </button>
                    )}

                    <button
                        className="sidebar-context-button"
                        onClick={() => navigate('/ativarsafra')}
                    >
                        <Sprout size={16} />
                        {!collapsed && <span>Trocar Safra</span>}
                    </button>

                </div>

                <hr className="sidebar-divider" />

                <nav className="sidebar-nav">

                    <NavLink to="/menu" className="sidebar-item" data-label="Menu">
                        <Home size={18} />
                        {!collapsed && <span>Menu</span>}
                    </NavLink>

                    {/* 🔥 NOVO: ORDEM DE SERVIÇO */}
                    <NavLink to="/ordens-servico" className="sidebar-item" data-label="Ordem de Serviço">
                        <ClipboardList size={18} />
                        {!collapsed && <span>Ordem de Serviço</span>}
                    </NavLink>

                    {/* 🔥 NOVO: ADUBAÇÃO */}
                    <NavLink to="/planejamento/adubacao" className="sidebar-item" data-label="Adubação">
                        <BarChart3 size={18} />
                        {!collapsed && <span>Adubação</span>}
                    </NavLink>

                    <NavLink to="/pedidos-compra" className="sidebar-item">
                      <ShoppingCart size={18} />
                      {!collapsed && <span>Compras</span>}
                    </NavLink>

                    {/* 🔥 NOVO: DASHBOARD */}
                    <NavLink to="/dashboard-safra" className="sidebar-item" data-label="Dashboard Safra">
                        <BarChart3 size={18} />
                        {!collapsed && <span>Dashboard Safra</span>}
                    </NavLink>

                    <NavLink to="/relatorio" className="sidebar-item">
                      📊 {!collapsed && <span>Relatório</span>}
                    </NavLink>

                    {/* FINANCEIRO */}
                    <button
                        className={`sidebar-item ${openFinanceiro ? 'active' : ''}`}
                        onClick={() => setOpenFinanceiro(prev => !prev)}
                        style={{ width: '100%', background: 'none', border: 'none' }}
                        data-label="Financeiro"
                    >
                        <DollarSign size={18} />
                        {!collapsed && (
                            <>
                                <span style={{ flex: 1 }}>Financeiro</span>
                                {openFinanceiro ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                            </>
                        )}
                    </button>

                    {openFinanceiro && !collapsed && (
                        <>
                            <NavLink to="/contas-pagar" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Contas a Pagar">
                                <span>Contas a Pagar</span>
                            </NavLink>

                            <NavLink to="/contas-receber" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Contas a Receber">
                                <span>Contas a Receber</span>
                            </NavLink>

                            <NavLink to="/fluxo-caixa" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Fluxo de Caixa">
                                <span>Fluxo de Caixa</span>
                            </NavLink>
                        </>
                    )}

                    <NavLink to="/funcionarios" className="sidebar-item" data-label="Funcionários">
                        <Users size={18} />
                        {!collapsed && <span>Funcionários</span>}
                    </NavLink>

                    <NavLink to="/folha" className="sidebar-item">
                      <DollarSign size={20} style={{ marginRight: 8 }} />
                      {!collapsed && <span>Folha Pagto.</span>}
                    </NavLink>

                    <NavLink to="/maquinas" className="sidebar-item" data-label="Máquinas">
                        <Tractor size={18} />
                        {!collapsed && <span>Máquinas</span>}
                    </NavLink>

                    {/* PRODUTOS */}
                    <button
                        className={`sidebar-item ${openProdutos ? 'active' : ''}`}
                        onClick={() => setOpenProdutos(prev => !prev)}
                        style={{ width: '100%', background: 'none', border: 'none' }}
                        data-label="Produtos"
                    >
                        <Package size={18} />
                        {!collapsed && (
                            <>
                                <span style={{ flex: 1 }}>Produtos</span>
                                {openProdutos ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                            </>
                        )}
                    </button>

                    {openProdutos && !collapsed && (
                        <>
                            <NavLink to="/produtos" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Lista de Produtos">
                                <span>Lista</span>
                            </NavLink>

                            <NavLink to="/produtos/movimentar" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Movimentação">
                                <span>Movimentação</span>
                            </NavLink>
                        </>
                    )}

                    {/* TALHÕES */}
                    <button
                        className={`sidebar-item ${openTalhoes ? 'active' : ''}`}
                        onClick={() => setOpenTalhoes(prev => !prev)}
                        style={{ width: '100%', background: 'none', border: 'none' }}
                        data-label="Talhões"
                    >
                        <Map size={18} />
                        {!collapsed && (
                            <>
                                <span style={{ flex: 1 }}>Talhões</span>
                                {openTalhoes ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                            </>
                        )}
                    </button>

                    {openTalhoes && !collapsed && (
                        <>
                            <NavLink to="/talhoes" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Lista de Talhões">
                                <span>Lista de Talhões</span>
                            </NavLink>

                            <NavLink to="/safra-talhoes" className="sidebar-item" style={{ paddingLeft: '36px' }} data-label="Safra Talhões">
                                <span>Safra Talhões</span>
                            </NavLink>
                        </>
                    )}

                    <NavLink to="/terceirizados" className="sidebar-item" data-label="Terceirizados">
                        <UserCog size={18} />
                        {!collapsed && <span>Terceirizados</span>}
                    </NavLink>

                    <NavLink to="/turmas-terceirizadas" className="sidebar-item" data-label="Turmas">
                        <Users size={18} />
                        {!collapsed && <span>Turmas</span>}
                    </NavLink>

                </nav>

            </aside>
        </>
    )
}

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'

import { useQuery } from '@tanstack/react-query'
import {
  obterAdubacaoSafra,
  criarPedidoCompra,
  listarProdutos
} from '../api/api'

import AdubacaoChart from '../components/AdubacaoChart'

export default function AdubacaoPage() {

  const navigate = useNavigate()

  const [safraId, setSafraId] = useState(1)
  const [erro, setErro] = useState('')
  const [data, setData] = useState(null)
  const [produtos, setProdutos] = useState([])

  const {
    data: response,
    isLoading
  } = useQuery({
    queryKey: ['adubacao', safraId],
    queryFn: () => obterAdubacaoSafra(safraId),
    onError: () => setErro('Erro ao carregar dados')
  })

  useEffect(() => {
    if (!response?.data?.data) {
      setData(null)
      return
    }

    setData(response.data.data)
  }, [response])

  // 🔥 CARREGAR PRODUTOS
  useEffect(() => {
    async function carregarProdutos() {
      try {
        const res = await listarProdutos()

        setProdutos(
          res.data?.data?.content ||
          res.data?.data ||
          []
        )
      } catch (err) {
        console.error(err)
      }
    }

    carregarProdutos()
  }, [])

  function formatar(valor) {
    return Number(valor || 0).toLocaleString('pt-BR')
  }

  // 🔥 NOVO
  async function gerarPedido() {
    try {

      const itens = data.totalGeral.map(p => {

        const produto = produtos.find(prod => prod.id === p.produtoId)

        return {
          produtoId: p.produtoId,
          quantidade: Number(p.quantidadeTotal),
          valorUnitario: produto?.precoCusto || 0
        }
      })

      const payload = { itens }

      const res = await criarPedidoCompra(payload)

      const id =
        res.data?.data?.id ||
        res.data?.data?.data?.id

      if (!id) {
        setErro('Erro ao gerar pedido')
        return
      }

      // 🔥 REDIRECIONA
      navigate(`/pedidos-compra/${id}/editar`)

    } catch (err) {
      console.error(err)
      setErro('Erro ao gerar pedido')
    }
  }

  if (isLoading) {
    return <PageLayout title="Adubação">Carregando...</PageLayout>
  }

  if (!data) {
    return (
      <PageLayout title="Adubação">
        <Alert type="error" message="Nenhum dado encontrado" />
      </PageLayout>
    )
  }

  return (
    <PageLayout title="Adubação">

      {erro && <Alert type="error" message={erro} />}

      <div style={{ marginBottom: 20 }}>
        <label>Safra: </label>
        <input
          type="number"
          value={safraId}
          onChange={(e) => setSafraId(e.target.value)}
        />
      </div>

      <div className="card" style={{ marginBottom: 20 }}>
        <h3>Total Geral</h3>

        {data.totalGeral
          ?.sort((a, b) => b.quantidadeTotal - a.quantidadeTotal)
          .map(item => (
            <div key={item.produtoId}>
              {item.produtoNome}:{' '}
              <strong>{formatar(item.quantidadeTotal)} kg</strong>
            </div>
          ))}

        <AdubacaoChart data={data.totalGeral} />

        <button
          className="add-btn"
          style={{ marginTop: 15 }}
          onClick={gerarPedido}
        >
          Gerar Pedido de Compra
        </button>

      </div>

      {data.talhoes?.map(t => (
        <div key={t.talhaoId} className="card">
          <h4>{t.talhaoNome}</h4>

          <table width="100%">
            <tbody>
              {t.produtos.map(p => (
                <tr key={p.produtoId}>
                  <td>{p.produtoNome}</td>
                  <td>{formatar(p.quantidadeTotal)} kg</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ))}

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useQueryClient } from '@tanstack/react-query'
import '../styles/pages.css'
import '../styles/form.css'
import Alert from '../components/Alert'
import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import {
    verificarCpf,
    criarFuncionario,
    buscarFuncionario,
    atualizarFuncionario
} from '../api/api'

export default function FuncionarioForm() {
    const navigate = useNavigate()
    const { id } = useParams()
    const modoEdicao = !!id
    const queryClient = useQueryClient()

    const [cpf, setCpf] = useState('')
    const [nome, setNome] = useState('')
    const [email, setEmail] = useState('')
    const [celular, setCelular] = useState('')
    const [endereco, setEndereco] = useState('')
    const [bairro, setBairro] = useState('')
    const [cidade, setCidade] = useState('')
    const [estado, setEstado] = useState('')
    const [cargo, setCargo] = useState('')
    const [salario, setSalario] = useState('')
    const [dtAdmissao, setDtAdmissao] = useState('')

    const [cpfVerificado, setCpfVerificado] = useState(modoEdicao)
    const [erro, setErro] = useState('')
    function formatarCpf(valor) {
        valor = valor.replace(/\D/g, '')
        valor = valor.replace(/^(\d{3})(\d)/, '$1.$2')
        valor = valor.replace(/^(\d{3})\.(\d{3})(\d)/, '$1.$2.$3')
        valor = valor.replace(/\.(\d{3})(\d)/, '.$1-$2')
        return valor.slice(0, 14)
    }

    useEffect(() => {
        async function carregarFuncionario() {
            try {
                const response = await buscarFuncionario(id)
                if (!response.ok || !response.data?.data) {
                    setErro('Erro ao carregar funcionário')
                    return
                }

                const f = response.data.data

                setCpf(formatarCpf(f.cpf || ''))
                setNome(f.nome || '')
                setEmail(f.email || '')
                setCelular(f.celular || '')
                setEndereco(f.endereco || '')
                setBairro(f.bairro || '')
                setCidade(f.cidade || '')
                setEstado(f.estado || '')
                setCargo(f.cargo || '')
                setSalario(f.salario ?? '')
                setDtAdmissao(f.dtAdmissao || '')
            } catch (err) {
                console.error(err)
                setErro('Erro ao carregar funcionário')
            }
        }

        if (modoEdicao) carregarFuncionario()
    }, [id, modoEdicao])

    function limparCpf(valor) {
        return valor.replace(/\D/g, '')
    }

    function handleCpfChange(e) {
        const valor = formatarCpf(e.target.value)
        setCpf(valor)
        setCpfVerificado(false)
        setErro('')
        setSucesso('')
    }

    async function validarCpfNoBackend(valorCpf) {
        setErro('')
        setSucesso('')

        const cpfLimpo = limparCpf(valorCpf)

        if (cpfLimpo.length !== 11) {
            setErro('Informe um CPF válido')
            setCpfVerificado(false)
            return false
        }

        try {
            const response = await verificarCpf(cpfLimpo)

            if (!response.data?.success) {
                setErro(response.data?.message || 'Erro ao verificar CPF')
                setCpfVerificado(false)
                return false
            }

            const disponivel = response.data.data

            if (disponivel === false && !modoEdicao) {
                setErro('CPF já cadastrado')
                setCpfVerificado(false)
                return false
            }

            setCpfVerificado(true)
            return true
        } catch (error) {
            console.error(error)
            setErro('Erro ao verificar CPF')
            setCpfVerificado(false)
            return false
        }
    }

    async function handleSubmit(e) {
        e.preventDefault()
        setErro('')
        setSucesso('')

        const cpfLimpo = limparCpf(cpf)

        if (!modoEdicao) {
            const valido = await validarCpfNoBackend(cpf)
            if (!valido) return
        }

        if (!nome) {
            setErro('Informe o nome do funcionário')
            return
        }

        const payload = {
            cpf: cpfLimpo,
            nome,
            email,
            celular,
            endereco,
            bairro,
            cidade,
            estado,
            cargo,
            salario: salario ? Number(salario) : null,
            dtAdmissao
        }

        try {
            const response = modoEdicao
                ? await atualizarFuncionario(id, payload)
                : await criarFuncionario(payload)

            if (!response.ok || !response.data?.success) {
                setErro(response.data?.message || 'Erro ao salvar funcionário')
                return
            }

            setSucesso(
                modoEdicao
                    ? 'Funcionário atualizado com sucesso'
                    : 'Funcionário cadastrado com sucesso'
            )

            setTimeout(() => {
                queryClient.invalidateQueries(['funcionarios'])
                navigate('/funcionarios')
            }, 1200)

        } catch (err) {
            console.error(err)
            setErro('Erro ao salvar funcionário')
        }
    }

    return (
        <PageLayout
            title={modoEdicao ? 'Editar Funcionário' : 'Novo Funcionário'}
            showBack
            backTo="/funcionarios"
        >
            {erro && <Alert type="error" message={erro} />}
            {sucesso && <Alert type="success" message={sucesso} />}

            <form className="form-container" onSubmit={handleSubmit}>

                {!modoEdicao && (
                    <FormInput
                        label="CPF"
                        value={cpf}
                        onChange={handleCpfChange}
                        onBlur={() => validarCpfNoBackend(cpf)}
                        onKeyDown={async (e) => { // 🔥 VOLTOU ENTER
                            if (e.key === 'Enter') {
                                e.preventDefault()
                                await validarCpfNoBackend(cpf)
                            }
                        }}
                        placeholder="000.000.000-00"
                        style={{ maxWidth: '220px' }}
                    />
                )}

                {(cpfVerificado || modoEdicao) && (
                    <>

                        <FormInput
                            label="Nome"
                            value={nome}
                            onChange={e => setNome(e.target.value)}
                            uppercase
                            required
                        />

                        <div className="form-grid-4">
                            <div style={{ gridColumn: 'span 3' }}>
                                <FormInput
                                    label="E-mail"
                                    type="email"
                                    value={email}
                                    onChange={e => setEmail(e.target.value)}
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Celular"
                                    value={celular}
                                    onChange={e => setCelular(e.target.value)}
                                />
                            </div>
                        </div>

                        <FormInput
                            label="Endereço"
                            value={endereco}
                            onChange={e => setEndereco(e.target.value)}
                            uppercase
                        />

                        <div className="form-grid-5">
                            <div style={{ gridColumn: 'span 2' }}>
                                <FormInput
                                    label="Bairro"
                                    value={bairro}
                                    onChange={e => setBairro(e.target.value)}
                                    uppercase
                                />
                            </div>
                            <div style={{ gridColumn: 'span 2' }}>
                                <FormInput
                                    label="Cidade"
                                    value={cidade}
                                    onChange={e => setCidade(e.target.value)}
                                    uppercase
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Estado"
                                    value={estado}
                                    onChange={e => setEstado(e.target.value)}
                                    maxLength={2}
                                    uppercase
                                />
                            </div>
                        </div>

                        <div className="form-grid-4">
                            <div style={{ gridColumn: 'span 2' }}>
                                <FormInput
                                    label="Cargo"
                                    value={cargo}
                                    onChange={e => setCargo(e.target.value)}
                                    uppercase
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Salário"
                                    type="number"
                                    value={salario}
                                    onChange={e => setSalario(e.target.value)}
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Data de Admissão"
                                    type="date"
                                    value={dtAdmissao}
                                    onChange={e => setDtAdmissao(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="form-actions">
                            <button type="submit" className="add-btn">
                                {modoEdicao ? 'Salvar alterações' : 'Salvar funcionário'}
                            </button>
                        </div>

                    </>
                )}

            </form>
        </PageLayout>
    )
}

import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useAuth } from '../auth/AuthContext'
import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'
import CrudCardList from '../components/CrudCardList'
import CrudCard from '../components/CrudCard'
import EmptyState from '../components/EmptyState'
import SkeletonCard from '../components/SkeletonCard'
import {
    buscarMaquina,
    listarHorasMaquina,
    listarGastosMaquina
} from '../api/api'
import { Plus } from 'lucide-react'

export default function MaquinaDetalhe() {
    const { id } = useParams()
    const navigate = useNavigate()
    const { user, safraAtiva } = useAuth()

    const fazendaId = user?.fazendaAtiva?.id
    const safraId = safraAtiva?.id

    const [maquina, setMaquina] = useState(null)
    const [horas, setHoras] = useState([])
    const [gastos, setGastos] = useState([])
    const [aba, setAba] = useState('horas')
    const [loading, setLoading] = useState(true)
    const [erro, setErro] = useState('')

    useEffect(() => {
        carregarDados()
    }, [id, safraId])

    async function carregarDados() {
        try {
            setLoading(true)

            const maquinaRes = await buscarMaquina(id)
            if (!maquinaRes.ok || !maquinaRes.data?.data) {
                setErro('Erro ao carregar máquina')
                return
            }

            setMaquina(maquinaRes.data.data)

            if (fazendaId && safraId) {
                const horasRes = await listarHorasMaquina({
                    maquinaId: Number(id),
                    fazendaId,
                    safraId
                })

                const gastosRes = await listarGastosMaquina({
                    maquinaId: Number(id),
                    fazendaId,
                    safraId
                })

                if (horasRes.ok) {
                    setHoras(horasRes.data?.data || [])
                }

                if (gastosRes.ok) {
                    setGastos(gastosRes.data?.data || [])
                }
            }

        } catch (error) {
            setErro('Erro ao carregar dados')
        } finally {
            setLoading(false)
        }
    }

    /* =============================
       CÁLCULOS (CORRIGIDO)
    ============================= */

    const listaHoras = Array.isArray(horas) ? horas : []
    const listaGastos = Array.isArray(gastos) ? gastos : []

    const totalHoras = listaHoras.reduce(
        (acc, h) => acc + Number(h.horasTrabalhadas || 0),
        0
    )

    // 🔥 NOVO: usa custoHora
    const custoTotalHoras = listaHoras.reduce(
        (acc, h) =>
            acc +
            Number(h.horasTrabalhadas || 0) *
            Number(h.custoHora || 0),
        0
    )

    const totalGastos = listaGastos.reduce(
        (acc, g) => acc + Number(g.valor || 0),
        0
    )

    const custoTotal = custoTotalHoras + totalGastos

    const custoPorHora =
        totalHoras > 0 ? (custoTotal / totalHoras).toFixed(2) : 0

    /* =============================
       RENDER
    ============================= */

    return (
        <PageLayout
            title="Detalhes da Máquina"
            showBack
            backTo="/maquinas"
        >
            {erro && <Alert type="error" message={erro} />}
            {loading && <SkeletonCard />}

            {!loading && maquina && (
                <>
                    {/* IDENTIFICAÇÃO */}
                    <CrudCard
                        title={maquina.nome}
                        subtitle={`${maquina.marca || '-'} / ${maquina.modelo || '-'}`}
                        ativo={maquina.ativo}
                    />

                    {/* KPI GRID */}
                    <div className="kpi-grid">

                        <div className="kpi-card kpi-blue">
                            <div className="kpi-value">
                                {totalHoras.toFixed(2)}h
                            </div>
                            <div className="kpi-label">
                                Total Horas (Safra)
                            </div>
                        </div>

                        <div className="kpi-card kpi-red">
                            <div className="kpi-value">
                                R$ {custoTotal.toFixed(2)}
                            </div>
                            <div className="kpi-label">
                                Custo Total
                            </div>
                        </div>

                        <div className="kpi-card kpi-purple">
                            <div className="kpi-value">
                                R$ {custoPorHora}
                            </div>
                            <div className="kpi-label">
                                Custo por Hora
                            </div>
                        </div>

                        <div className="kpi-card kpi-green">
                            <div className="kpi-value">
                                {maquina.horimetro || 0}h
                            </div>
                            <div className="kpi-label">
                                Horímetro Atual
                            </div>
                        </div>

                    </div>

                    {/* TABS + BOTÃO */}
                    <div
                        style={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            alignItems: 'center',
                            marginTop: 32
                        }}
                    >
                        <div className="segmented-control">
                            <button
                                className={`segmented-button ${aba === 'horas' ? 'active' : ''}`}
                                onClick={() => setAba('horas')}
                            >
                                Horas
                            </button>

                            <button
                                className={`segmented-button ${aba === 'gastos' ? 'active' : ''}`}
                                onClick={() => setAba('gastos')}
                            >
                                Gastos
                            </button>
                        </div>

                        <button
                            className="add-btn"
                            onClick={() =>
                                navigate(
                                    aba === 'horas'
                                        ? `/maquinas/${id}/horas/nova`
                                        : `/maquinas/${id}/gastos/nova`
                                )
                            }
                        >
                            <Plus size={16} /> Novo
                        </button>
                    </div>

                    {/* LISTA */}
                    {aba === 'horas' && (
                        <>
                            {listaHoras.length === 0 && (
                                <EmptyState message="Nenhuma hora lançada nesta safra." />
                            )}

                            <CrudCardList>
                                {listaHoras.map(h => (
                                    <CrudCard
                                        key={h.id}
                                        title={`Data: ${h.dataExecucao}`}
                                        subtitle={`Horas: ${h.horasTrabalhadas} | R$ ${Number(h.custoHora || 0).toFixed(2)}/h`}
                                    />
                                ))}
                            </CrudCardList>
                        </>
                    )}

                    {aba === 'gastos' && (
                        <>
                            {listaGastos.length === 0 && (
                                <EmptyState message="Nenhum gasto lançado nesta safra." />
                            )}

                            <CrudCardList>
                                {listaGastos.map(g => (
                                    <CrudCard
                                        key={g.id}
                                        title={`Data: ${g.data}`}
                                        subtitle={`R$ ${Number(g.valor || 0).toFixed(2)}`}
                                    />
                                ))}
                            </CrudCardList>
                        </>
                    )}
                </>
            )}
        </PageLayout>
    )
}

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import '../styles/pages.css'
import '../styles/form.css'
import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'
import FormInput from '../components/FormInput'
import {
    criarMaquina,
    atualizarMaquina,
    buscarMaquina,
    listarTiposMaquina
} from '../api/api'

export default function MaquinaForm() {
    const navigate = useNavigate()
    const { id } = useParams()
    const modoEdicao = !!id

    const [nome, setNome] = useState('')
    const [marca, setMarca] = useState('')
    const [modelo, setModelo] = useState('')
    const [descricao, setDescricao] = useState('')
    const [anoFabricacao, setAnoFabricacao] = useState('')
    const [horimetro, setHorimetro] = useState('')
    const [tipoMaquinaId, setTipoMaquinaId] = useState('')
    const [tipos, setTipos] = useState([])

    const [erro, setErro] = useState('')
    const [sucesso, setSucesso] = useState('')

    useEffect(() => {
        async function carregarTipos() {
            const response = await listarTiposMaquina()

            if (response.ok && response.data?.success) {
                setTipos(response.data.data)
            } else {
                setErro('Erro ao carregar tipos de máquina')
            }
        }

        async function carregarMaquina() {
            const response = await buscarMaquina(id)

            if (!response.ok || !response.data?.data) {
                setErro('Erro ao carregar máquina')
                return
            }

            const m = response.data.data

            setNome(m.nome || '')
            setMarca(m.marca || '')
            setModelo(m.modelo || '')
            setDescricao(m.descricao || '')
            setAnoFabricacao(m.anoFabricacao || '')
            setHorimetro(m.horimetro || 0)
            setTipoMaquinaId(m.tipoMaquina?.id || '')
        }

        carregarTipos()
        if (modoEdicao) {
            carregarMaquina()
        }
    }, [id, modoEdicao])

    async function handleSubmit(e) {
        e.preventDefault()
        setErro('')
        setSucesso('')

        if (!nome) {
            setErro('Informe o nome da máquina')
            return
        }

        if (!tipoMaquinaId) {
            setErro('Selecione o tipo da máquina')
            return
        }

        const payload = {
            nome,
            marca,
            modelo,
            descricao,
            anoFabricacao: anoFabricacao ? Number(anoFabricacao) : null,
            horimetro: horimetro ? Number(horimetro) : 0,
            tipoMaquinaId: Number(tipoMaquinaId)
        }

        try {
            const response = modoEdicao
                ? await atualizarMaquina(id, payload)
                : await criarMaquina(payload)

            if (!response.ok || !response.data?.success) {
                setErro(response.data?.message || 'Erro ao salvar máquina')
                return
            }

            setSucesso(
                modoEdicao
                    ? 'Máquina atualizada com sucesso'
                    : 'Máquina cadastrada com sucesso'
            )

            setTimeout(() => {
                navigate('/maquinas')
            }, 1200)

        } catch (err) {
            setErro('Erro ao salvar máquina')
        }
    }

    return (
        <PageLayout
            title={modoEdicao ? 'Editar Máquina' : 'Nova Máquina'}
            showBack
            backTo="/maquinas"
        >
            {erro && <Alert type="error" message={erro} />}
            {sucesso && <Alert type="success" message={sucesso} />}

            <form className="form-container" onSubmit={handleSubmit}>

                <FormInput
                    label="Nome"
                    value={nome}
                    onChange={e => setNome(e.target.value)}
                    uppercase
                    required
                />

                {/* TIPO + ANO */}
                <div className="form-grid-4">
                    <div style={{ gridColumn: 'span 2' }}>
                        <label className="form-label">Tipo de Máquina</label>
                        <select
                            className="form-input"
                            value={tipoMaquinaId}
                            onChange={e => setTipoMaquinaId(e.target.value)}
                            required
                        >
                            <option value="">Selecione...</option>
                            {tipos.map(t => (
                                <option key={t.id} value={t.id}>
                                    {t.descricao}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div style={{ gridColumn: 'span 2' }}>
                        <FormInput
                            label="Ano de Fabricação"
                            type="number"
                            value={anoFabricacao}
                            onChange={e => setAnoFabricacao(e.target.value)}
                        />
                    </div>
                </div>

                {/* MARCA + MODELO */}
                <div className="form-grid-4">
                    <div style={{ gridColumn: 'span 2' }}>
                        <FormInput
                            label="Marca"
                            value={marca}
                            onChange={e => setMarca(e.target.value)}
                            uppercase
                        />
                    </div>

                    <div style={{ gridColumn: 'span 2' }}>
                        <FormInput
                            label="Modelo"
                            value={modelo}
                            onChange={e => setModelo(e.target.value)}
                            uppercase
                        />
                    </div>
                </div>

                <FormInput
                    label="Descrição"
                    value={descricao}
                    onChange={e => setDescricao(e.target.value)}
                    uppercase
                />

                <FormInput
                    label="Horímetro Inicial"
                    type="number"
                    value={horimetro}
                    onChange={e => setHorimetro(e.target.value)}
                />

                <div className="form-actions">
                    <button type="submit" className="add-btn">
                        {modoEdicao ? 'Salvar alterações' : 'Salvar máquina'}
                    </button>
                </div>

            </form>
        </PageLayout>
    )
}

import { useState, useEffect, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../auth/AuthContext'
import '../styles/pages.css'
import '../styles/form.css'
import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'
import FormInput from '../components/FormInput'
import {
    listarProdutos,
    criarMovProduto
} from '../api/api'

export default function MovProdutoForm() {
    const navigate = useNavigate()
    const { user, safraAtiva } = useAuth()

    const fazendaId = user?.fazendaAtiva?.id
    const safraId = safraAtiva?.id

    const [fornecedor, setFornecedor] = useState('')
    const [numeroNotaFiscal, setNumeroNotaFiscal] = useState('')
    const [dataEntrada, setDataEntrada] = useState('')
    const [dataVencimento, setDataVencimento] = useState('')

    const [produtos, setProdutos] = useState([])
    const [itens, setItens] = useState([
        { produtoId: '', quantidade: '', valorUnitario: '' }
    ])

    const refs = useRef([])
    const addButtonRef = useRef(null)

    const [erro, setErro] = useState('')
    const [sucesso, setSucesso] = useState('')

    const dadosNotaPreenchidos =
        fornecedor &&
        numeroNotaFiscal &&
        dataEntrada &&
        dataVencimento
    useEffect(() => {
        if (dadosNotaPreenchidos) {
            setTimeout(() => {
                refs.current[0]?.produto?.focus()
            }, 100)
        }
    }, [dadosNotaPreenchidos])    useEffect(() => {
        async function carregarProdutos() {
            const response = await listarProdutos()
            if (response.ok && response.data?.data?.content) {
                setProdutos(response.data.data.content)
            }
        }
        carregarProdutos()
    }, [])

    function adicionarItem() {
        setItens(prev => [
            ...prev,
            { produtoId: '', quantidade: '', valorUnitario: '' }
        ])

        setTimeout(() => {
            refs.current[itens.length]?.produto?.focus()
        }, 100)
    }

    function removerItem(index) {
        const novos = [...itens]
        novos.splice(index, 1)
        setItens(novos)
    }

    function atualizarItem(index, campo, valor) {
        const novos = [...itens]
        novos[index][campo] = valor
        setItens(novos)
    }

    function handleEnter(e, index, campo) {
        if (e.key === 'Enter') {
            e.preventDefault()

            if (campo === 'produto') {
                refs.current[index]?.qtd?.focus()
            }

            if (campo === 'qtd') {
                refs.current[index]?.vlr?.focus()
            }

            if (campo === 'vlr') {
                addButtonRef.current?.focus()
            }
        }
    }

    function validarItens() {
        for (let i = 0; i < itens.length; i++) {
            const item = itens[i]

            if (!item.produtoId) {
                return `Item ${i + 1}: selecione o produto`
            }

            if (!item.quantidade || Number(item.quantidade) <= 0) {
                return `Item ${i + 1}: quantidade deve ser maior que zero`
            }

            if (!item.valorUnitario || Number(item.valorUnitario) <= 0) {
                return `Item ${i + 1}: valor unitário deve ser maior que zero`
            }
        }

        return null
    }

    const totalNota = itens.reduce((acc, item) => {
        const qtd = Number(item.quantidade) || 0
        const vlr = Number(item.valorUnitario) || 0
        return acc + (qtd * vlr)
    }, 0)

    async function handleSubmit(e) {
        e.preventDefault()
        setErro('')
        setSucesso('')

        if (!dadosNotaPreenchidos) {
            setErro('Preencha os dados da nota')
            return
        }

        const erroValidacao = validarItens()
        if (erroValidacao) {
            setErro(erroValidacao)
            return
        }

        const payload = {
            fornecedor,
            numeroNotaFiscal,
            dataEntrada,
            dataVencimento,
            itens: itens.map(i => ({
                produtoId: Number(i.produtoId),
                quantidade: Number(i.quantidade),
                valorUnitario: Number(i.valorUnitario)
            }))
        }

        const response = await criarMovProduto(payload)

        if (!response.ok || !response.data?.success) {
            setErro(response.data?.message || 'Erro ao salvar movimentação')
            return
        }

        setSucesso('Movimentação registrada com sucesso')

        setTimeout(() => {
            navigate('/produtos')
        }, 1200)
    }

    return (
        <PageLayout title="Movimentação de Produtos" showBack backTo="/produtos">

            {erro && <Alert type="error" message={erro} />}
            {sucesso && <Alert type="success" message={sucesso} />}

            <form className="form-container" onSubmit={handleSubmit}>

                <div className="form-grid-4">
                    <FormInput label="Fornecedor" value={fornecedor} onChange={e => setFornecedor(e.target.value)} uppercase />
                    <FormInput label="Nota Fiscal" value={numeroNotaFiscal} onChange={e => setNumeroNotaFiscal(e.target.value)} uppercase />
                    <FormInput label="Data Entrada" type="date" value={dataEntrada} onChange={e => setDataEntrada(e.target.value)} />
                    <FormInput label="Data Vencimento" type="date" value={dataVencimento} onChange={e => setDataVencimento(e.target.value)} />
                </div>

                {!dadosNotaPreenchidos && (
                    <p style={{ color: '#999', marginTop: 10 }}>
                        Preencha os dados da nota para liberar os itens
                    </p>
                )}

                <div style={{
                    marginTop: 10,
                    border: '1px solid #ddd',
                    borderRadius: 8,
                    opacity: dadosNotaPreenchidos ? 1 : 0.5,
                    pointerEvents: dadosNotaPreenchidos ? 'auto' : 'none'
                }}>

                    <div style={{
                        display: 'grid',
                        gridTemplateColumns: '3fr 1fr 1fr 40px',
                        background: '#f5f5f5',
                        padding: 10,
                        fontWeight: 600
                    }}>
                        <div>Produto</div>
                        <div>Qtd</div>
                        <div>Vlr Unit</div>
                        <div></div>
                    </div>

                    {itens.map((item, index) => {
                        if (!refs.current[index]) refs.current[index] = {}

                        return (
                            <div key={index} style={{
                                display: 'grid',
                                gridTemplateColumns: '3fr 1fr 1fr 40px',
                                padding: 8,
                                borderTop: '1px solid #eee',
                                alignItems: 'center'
                            }}>

                                <select
                                    ref={el => refs.current[index].produto = el}
                                    className="form-input"
                                    value={item.produtoId}
                                    onChange={e => atualizarItem(index, 'produtoId', e.target.value)}
                                    onKeyDown={(e) => handleEnter(e, index, 'produto')}
                                >
                                    <option value="">Selecione</option>
                                    {produtos.map(p => (
                                        <option key={p.id} value={p.id}>
                                            {p.nome}
                                        </option>
                                    ))}
                                </select>

                                <input
                                    ref={el => refs.current[index].qtd = el}
                                    className="form-input"
                                    type="number"
                                    value={item.quantidade}
                                    onChange={e => atualizarItem(index, 'quantidade', e.target.value)}
                                    onKeyDown={(e) => handleEnter(e, index, 'qtd')}
                                />

                                <input
                                    ref={el => refs.current[index].vlr = el}
                                    className="form-input"
                                    type="number"
                                    value={item.valorUnitario}
                                    onChange={e => atualizarItem(index, 'valorUnitario', e.target.value)}
                                    onKeyDown={(e) => handleEnter(e, index, 'vlr')}
                                />

                                <button
                                    type="button"
                                    onClick={() => removerItem(index)}
                                    style={{
                                        color: '#c62828',
                                        border: 'none',
                                        background: 'transparent',
                                        cursor: 'pointer',
                                        display: 'flex',
                                        alignItems: 'center',
