import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'

import {
  listarPlanejamentos,
  criarOsFromPlanejamento
} from '../api/api'

export default function OrdemServicoForm() {

  const navigate = useNavigate()

  // 🔥 ALTERAÇÃO: agora é array
  const [planejamentoIds, setPlanejamentoIds] = useState([])
  const [planejamentos, setPlanejamentos] = useState([])

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  useEffect(() => {
    carregar()
  }, [])

  async function carregar() {
    try {
      const res = await listarPlanejamentos()

      console.log('PLANEJAMENTOS:', res.data)

      const lista = Array.isArray(res.data?.data?.content)
        ? res.data.data.content
        : Array.isArray(res.data?.data)
          ? res.data.data
          : []

      setPlanejamentos(lista)

    } catch (err) {
      console.error(err)
      setErro('Erro ao carregar planejamentos')
    }
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    // 🔥 ALTERAÇÃO: valida array
    if (planejamentoIds.length === 0) {
      setErro('Selecione pelo menos um planejamento')
      return
    }

    try {
      const res = await criarOsFromPlanejamento({
        // 🔥 ALTERAÇÃO: envia lista
        planejamentoIds: planejamentoIds.map(id => Number(id))
      })

      if (!res.data?.success) {
        setErro('Erro ao criar OS')
        return
      }

      setSucesso('Ordem de serviço criada')

      navigate('/ordens-servico')

    } catch (err) {
      console.error(err)
      setErro('Erro ao salvar')
    }
  }

  return (
    <PageLayout
      title="Nova Ordem de Serviço"
      showBack
      backTo="/ordens-servico"
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <form className="form-container" onSubmit={handleSubmit}>

        <div>
          <label>Planejamento</label>

          {/* 🔥 ALTERAÇÃO: multiple */}
          <select
            multiple
            value={planejamentoIds}
            onChange={e =>
              setPlanejamentoIds(
                Array.from(e.target.selectedOptions, option => option.value)
              )
            }
          >
            {planejamentos.map(p => (
              <option key={p.id} value={String(p.id)}>
                {p.operacaoNome || p.operacao?.nome || `Planejamento ${p.id}`}
              </option>
            ))}
          </select>
        </div>

        <div className="form-actions">
          <button type="submit" className="add-btn">
            Criar Ordem de Serviço
          </button>
        </div>

      </form>

    </PageLayout>
  )
