import { useState, useEffect } from 'react'
import { useParams } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'

import {
  listarTurmas,
  registrarApontamentoTurma,
  listarApontamentosTurmaPorOs
} from '../api/api'

export default function OrdemServicoTurmas() {

  const { id } = useParams()

  const [turmas, setTurmas] = useState([])
  const [turmaId, setTurmaId] = useState('')

  const [diasTrabalhados, setDiasTrabalhados] = useState('')
  const [quantidadeColhida, setQuantidadeColhida] = useState('')
  const [observacao, setObservacao] = useState('')

  const [apontamentos, setApontamentos] = useState([])

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  useEffect(() => {
    carregarTurmas()
    carregarApontamentos()
  }, [])

  async function carregarTurmas() {
    try {
      const res = await listarTurmas()
      setTurmas(res.data?.data || [])
    } catch (err) {
      setErro('Erro ao carregar turmas')
    }
  }

  async function carregarApontamentos() {
    try {
      const res = await listarApontamentosTurmaPorOs(id)
      setApontamentos(res.data?.data || [])
    } catch (err) {
      setErro('Erro ao carregar apontamentos')
    }
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    if (!turmaId) {
      setErro('Selecione a turma')
      return
    }

    try {
      await registrarApontamentoTurma({
        ordemServicoId: Number(id), // 🔥 NOVO
        turmaId: Number(turmaId),
        diasTrabalhados: diasTrabalhados ? Number(diasTrabalhados) : null,
        quantidadeColhida: quantidadeColhida ? Number(quantidadeColhida) : null,
        dataInicio: new Date().toISOString().split('T')[0],
        dataFim: new Date().toISOString().split('T')[0],
        observacao
      })

      setSucesso('Apontamento registrado com sucesso')

      setTurmaId('')
      setDiasTrabalhados('')
      setQuantidadeColhida('')
      setObservacao('')

      await carregarApontamentos()

    } catch (err) {
      console.error(err)
      setErro('Erro ao registrar apontamento')
    }
  }

  // 🔥 TOTAL POR TURMA
  const totalPorTurma = apontamentos.reduce((acc, a) => {
    const key = a.turmaNome || 'Sem nome'

    if (!acc[key]) acc[key] = 0

    acc[key] += Number(a.valorTotal || 0)

    return acc
  }, {})

  // 🔥 TOTAL GERAL
  const totalGeral = apontamentos.reduce(
    (t, a) => t + Number(a.valorTotal || 0),
    0
  )

  return (
    <PageLayout
      title="Turmas da OS"
      showBack
      backTo={`/ordens-servico/${id}`}
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <form className="form-container" onSubmit={handleSubmit}>

        <div>
          <label>Turma</label>
          <select
            value={turmaId}
            onChange={e => setTurmaId(e.target.value)}
          >
            <option value="">Selecione</option>
            {turmas.map(t => (
              <option key={t.id} value={String(t.id)}>
                {t.nome}
              </option>
            ))}
          </select>
        </div>

        <div className="form-grid-2">
          <div>
            <label>Dias Trabalhados</label>
            <input
              type="number"
              value={diasTrabalhados}
              onChange={e => setDiasTrabalhados(e.target.value)}
            />
          </div>

          <div>
            <label>Quantidade Colhida</label>
            <input
              type="number"
              value={quantidadeColhida}
              onChange={e => setQuantidadeColhida(e.target.value)}
            />
          </div>
        </div>

        <div>
          <label>Observação</label>
          <input
            value={observacao}
            onChange={e => setObservacao(e.target.value)}
          />
        </div>

        <div className="form-actions">
          <button type="submit" className="add-btn">
            Registrar Apontamento
          </button>
        </div>

      </form>

      {/* 🔥 LISTA */}
      {apontamentos.length > 0 && (
        <div style={{ marginTop: 20 }}>

          <table className="table-insumos compact">

            <thead>
              <tr>
                <th>Turma</th>
                <th>Período</th>
                <th>Dias</th>
                <th>Qtd Colhida</th>
                <th>Valor</th>
              </tr>
            </thead>

            <tbody>
              {apontamentos.map(a => (
                <tr key={a.id}>

                  <td>{a.turmaNome}</td>

                  <td>
                    {a.dataInicio} - {a.dataFim}
                  </td>

                  <td>{a.diasTrabalhados || '-'}</td>

                  <td>{a.quantidadeColhida || '-'}</td>

                  <td className="col-custo">
                    R$ {Number(a.valorTotal).toFixed(2)}
                  </td>

                </tr>
              ))}
            </tbody>

          </table>

        </div>
      )}

      {/* 🔥 RESUMO */}
      {apontamentos.length > 0 && (
        <div style={{ marginTop: 20 }}>

          <h4>Total por Turma</h4>

          <table className="table-insumos compact">
            <thead>
              <tr>
                <th>Turma</th>
                <th>Total</th>
              </tr>
            </thead>

            <tbody>
              {Object.entries(totalPorTurma).map(([nome, total]) => (
                <tr key={nome}>
                  <td>{nome}</td>
                  <td className="col-custo">
                    R$ {total.toFixed(2)}
                  </td>
                </tr>
              ))}
            </tbody>

            <tfoot>
              <tr>
                <td><strong>Total Geral</strong></td>
                <td className="col-custo">
                  <strong>R$ {totalGeral.toFixed(2)}</strong>
                </td>
              </tr>
            </tfoot>

          </table>

        </div>
      )}

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import Alert from '../components/Alert'

import {
  criarPedidoCompra,
  buscarPedidoCompra,
  atualizarPedidoCompra,
  listarProdutos
} from '../api/api'

export default function PedidoCompraForm() {

  const navigate = useNavigate()
  const { id } = useParams()

  const [itens, setItens] = useState([])
  const [produtos, setProdutos] = useState([])

  const [produtoId, setProdutoId] = useState('')
  const [quantidade, setQuantidade] = useState('')
  const [valorUnitario, setValorUnitario] = useState('')

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  useEffect(() => {
    async function carregarProdutos() {
      const res = await listarProdutos()
      setProdutos(res.data?.data || [])
    }

    async function carregar() {
      const res = await buscarPedidoCompra(id)
      setItens(res.data?.data?.itens || [])
    }

    carregarProdutos()
    if (id) carregar()
  }, [id])

  function adicionarItem() {
    if (!produtoId) return

    const novo = {
      produtoId: Number(produtoId),
      quantidade: Number(quantidade),
      valorUnitario: Number(valorUnitario),
      valorTotal: Number(quantidade) * Number(valorUnitario)
    }

    setItens(prev => [...prev, novo])

    setProdutoId('')
    setQuantidade('')
    setValorUnitario('')
  }

  async function salvar() {

    const payload = {
      itens
    }

    if (id) {
      await atualizarPedidoCompra(id, payload)
    } else {
      await criarPedidoCompra(payload)
    }

    setSucesso('Salvo com sucesso')

    setTimeout(() => navigate('/pedidos-compra'), 800)
  }

  const total = itens.reduce((t, i) => t + i.valorTotal, 0)

  return (
    <PageLayout title="Pedido de Compra" showBack backTo="/pedidos-compra">

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <div className="form-grid-3">

        <select value={produtoId} onChange={e => setProdutoId(e.target.value)}>
          <option value="">Produto</option>
          {produtos.map(p => (
            <option key={p.id} value={p.id}>{p.nome}</option>
          ))}
        </select>

        <FormInput
          type="number"
          placeholder="Qtd"
          value={quantidade}
          onChange={e => setQuantidade(e.target.value)}
        />

        <FormInput
          type="number"
          placeholder="Valor"
          value={valorUnitario}
          onChange={e => setValorUnitario(e.target.value)}
        />

      </div>

      <button className="add-btn" onClick={adicionarItem}>
        Adicionar Item
      </button>

      <table className="table-insumos">
        <tbody>
          {itens.map((i, idx) => (
            <tr key={idx}>
              <td>{i.produtoId}</td>
              <td>{i.quantidade}</td>
              <td>{i.valorUnitario}</td>
              <td>{i.valorTotal}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div style={{ marginTop: 20 }}>
        Total: R$ {total.toFixed(2)}
      </div>

      <button className="add-btn" onClick={salvar}>
        Salvar Pedido
      </button>

    </PageLayout>
  )
}

import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'
import SkeletonCard from '../components/SkeletonCard'

import { obterComparativoPlanejamento } from '../api/api'

export default function PlanejamentoComparativo() {

  const { id } = useParams()
  const navigate = useNavigate()

  const [dados, setDados] = useState(null)
  const [loading, setLoading] = useState(true)
  const [erro, setErro] = useState('')

  useEffect(() => {
    carregar()
  }, [])

  async function carregar() {
    try {
      const res = await obterComparativoPlanejamento(id)

      if (!res.data?.success) {
        setErro('Erro ao carregar comparativo')
        return
      }

      setDados(res.data.data)

    } catch (err) {
      console.error(err)
      setErro('Erro ao carregar comparativo')
    } finally {
      setLoading(false)
    }
  }

  function diferenca(previsto, realizado) {
    return (realizado || 0) - (previsto || 0)
  }

  return (
    <PageLayout
      title="Comparativo do Planejamento"
      showBack
      backTo={`/planejamento/${id}/resumo`}
    >

      {erro && <Alert type="error" message={erro} />}

      {loading && (
        <>
          <SkeletonCard />
          <SkeletonCard />
        </>
      )}

      {!loading && dados && (

        <div className="card-list">

          {/* 🔹 INSUMOS */}
          <div className="card">
            <strong>Insumos</strong>
            <p>Previsto: R$ {dados.insumosPrevisto}</p>
            <p>Realizado: R$ {dados.insumosRealizado}</p>
            <p>Diferença: R$ {diferenca(dados.insumosPrevisto, dados.insumosRealizado)}</p>
          </div>

          {/* 🔹 MÁQUINAS */}
          <div className="card">
            <strong>Máquinas</strong>
            <p>Previsto: R$ {dados.maquinasPrevisto}</p>
            <p>Realizado: R$ {dados.maquinasRealizado}</p>
            <p>Diferença: R$ {diferenca(dados.maquinasPrevisto, dados.maquinasRealizado)}</p>
          </div>

          {/* 🔹 MÃO DE OBRA */}
          <div className="card">
            <strong>Mão de Obra</strong>
            <p>Previsto: R$ {dados.maoObraPrevisto}</p>
            <p>Realizado: R$ {dados.maoObraRealizado}</p>
            <p>Diferença: R$ {diferenca(dados.maoObraPrevisto, dados.maoObraRealizado)}</p>
          </div>

          {/* 🔹 TOTAL */}
          <div className="card">
            <strong>Total Geral</strong>
            <p>Previsto: R$ {dados.totalPrevisto}</p>
            <p>Realizado: R$ {dados.totalRealizado}</p>
            <p>Diferença: R$ {diferenca(dados.totalPrevisto, dados.totalRealizado)}</p>
          </div>

        </div>
      )}

      {!loading && dados && (
        <div style={{ marginTop: 20 }}>
          <button
            className="add-btn"
            onClick={() => navigate(`/planejamento/${id}/comparativo-detalhado`)}
          >
            Ver Detalhado →
          </button>
        </div>
      )}

    </PageLayout>
  )
}

import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import Alert from '../components/Alert'
import SkeletonCard from '../components/SkeletonCard'

import { obterComparativoDetalhado } from '../api/api'

export default function PlanejamentoComparativoDetalhado() {

  const { id } = useParams()
  const navigate = useNavigate()

  const [dados, setDados] = useState(null)
  const [loading, setLoading] = useState(true)
  const [erro, setErro] = useState('')

  useEffect(() => {
    carregar()
  }, [])

  async function carregar() {
    try {
      const res = await obterComparativoDetalhado(id)

      if (!res.data?.success) {
        setErro('Erro ao carregar comparativo detalhado')
        return
      }

      setDados(res.data.data)

    } catch (err) {
      console.error(err)
      setErro('Erro ao carregar comparativo detalhado')
    } finally {
      setLoading(false)
    }
  }

  function diff(prev, real) {
    return (real || 0) - (prev || 0)
  }

  function renderLista(lista, labelNome) {
    if (!lista || lista.length === 0) {
      return <p>Nenhum registro</p>
    }

    return lista.map((item, index) => (
      <div key={index} className="card">
        <strong>{item[labelNome]}</strong>

        <p>Previsto: {item.previsto}</p>
        <p>Realizado: {item.realizado}</p>
        <p>Diferença: {diff(item.previsto, item.realizado)}</p>
      </div>
    ))
  }

  return (
    <PageLayout
      title="Comparativo Detalhado"
      showBack
      backTo={`/planejamento/${id}/comparativo`}
    >

      {erro && <Alert type="error" message={erro} />}

      {loading && (
        <>
          <SkeletonCard />
          <SkeletonCard />
        </>
      )}

      {!loading && dados && (

        <div className="card-list">

          {/* 🔹 INSUMOS */}
          <div>
            <h3>Insumos</h3>
            {renderLista(dados.insumos, 'produto')}
          </div>

          {/* 🔹 MÁQUINAS */}
          <div>
            <h3>Máquinas</h3>
            {renderLista(dados.maquinas, 'maquina')}
          </div>

          {/* 🔹 FUNCIONÁRIOS */}
          <div>
            <h3>Funcionários</h3>
            {renderLista(dados.funcionarios, 'nome')}
          </div>

        </div>
      )}

      {/* 🔥 FINAL */}
      {!loading && dados && (
        <div style={{ marginTop: 20 }}>
          <button
            className="add-btn"
            onClick={() => navigate(`/ordens-servico/novo?planejamentoId=${id}`)}
          >
            Gerar Ordem de Serviço →
          </button>
        </div>
      )}

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useAuth } from '../auth/AuthContext'

import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import Alert from '../components/Alert'

import {
  adicionarInsumoPlanejamento,
  listarProdutos
} from '../api/api'

export default function PlanejamentoInsumos() {

  const { id } = useParams()
  const navigate = useNavigate()
  const { user } = useAuth()

  const [produtoId, setProdutoId] = useState('')
  const [dosePorHa, setDosePorHa] = useState('')
  const [valorUnitarioPrevisto, setValorUnitarioPrevisto] = useState('')

  const [produtos, setProdutos] = useState([])
  const [insumosAdicionados, setInsumosAdicionados] = useState([])

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  const podeEditar = user?.perfilId === 2

  useEffect(() => {
    carregarProdutos()
  }, [])

  async function carregarProdutos() {
    try {
      const res = await listarProdutos()
      setProdutos(res.data?.data?.content || res.data?.data || [])
    } catch (err) {
      console.error(err)
      setErro('Erro ao carregar produtos')
    }
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    if (!podeEditar) {
      setErro('Você não tem permissão para adicionar insumos')
      return
    }

    if (!produtoId) {
      setErro('Selecione o produto')
      return
    }

    try {
      const res = await adicionarInsumoPlanejamento(id, {
        produtoId: Number(produtoId),
        dosePorHa: Number(dosePorHa),
        valorUnitarioPrevisto: Number(valorUnitarioPrevisto)
      })

      if (!res.data?.success) {
        setErro('Erro ao adicionar insumo')
        return
      }

      setSucesso('Insumo adicionado com sucesso')

      setInsumosAdicionados(prev => [
        ...prev,
        {
          produtoId,
          dosePorHa,
          valorUnitarioPrevisto
        }
      ])

      setProdutoId('')
      setDosePorHa('')
      setValorUnitarioPrevisto('')

    } catch (err) {
      console.error(err)
      setErro('Erro ao salvar')
    }
  }

  return (
    <PageLayout
      title="Insumos do Planejamento"
      showBack
      backTo="/safra-talhoes"
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <form className="form-container" onSubmit={handleSubmit}>

        <div>
          <label>Produto</label>
          <select
            value={produtoId}
            onChange={e => setProdutoId(e.target.value)}
            disabled={!podeEditar}
          >
            <option value="">Selecione</option>
            {produtos.map(p => (
              <option key={p.id} value={String(p.id)}>
                {p.nome}
              </option>
            ))}
          </select>
        </div>

        <FormInput
          label="Dose por Hectare"
          type="number"
          value={dosePorHa}
          onChange={e => setDosePorHa(e.target.value)}
          disabled={!podeEditar}
        />

        <FormInput
          label="Valor Unitário"
          type="number"
          value={valorUnitarioPrevisto}
          onChange={e => setValorUnitarioPrevisto(e.target.value)}
          disabled={!podeEditar}
        />

        {podeEditar && (
          <div className="form-actions">
            <button type="submit" className="add-btn">
              Adicionar Insumo
            </button>
          </div>
        )}

      </form>

      {/* 🔥 LISTA LOCAL */}
      {insumosAdicionados.length > 0 && (
        <div className="card-list">
          {insumosAdicionados.map((i, index) => (
            <div key={index} className="card">
              Produto: {i.produtoId} | Dose: {i.dosePorHa} | Valor: {i.valorUnitarioPrevisto}
            </div>
          ))}
        </div>
      )}

      {/* 🔥 FLUXO → MÁQUINAS */}
      <div style={{ marginTop: 20 }}>
        <button
          className="add-btn"
          onClick={() => navigate(`/planejamento/${id}/maquinas`)}
        >
          Avançar para Máquinas →
        </button>
      </div>

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useParams } from 'react-router-dom'

import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import Alert from '../components/Alert'

import {
  listarFuncionarios,
  listarTerceirizados,
  listarTurmas,
  adicionarFuncionarioPlanejamento
} from '../api/api'

export default function PlanejamentoFuncionarios() {

  const { id } = useParams()

  const [tipo, setTipo] = useState('FUNCIONARIO')

  const [funcionarios, setFuncionarios] = useState([])
  const [terceirizados, setTerceirizados] = useState([])
  const [turmas, setTurmas] = useState([])

  const [funcionarioId, setFuncionarioId] = useState('')
  const [terceirizadoId, setTerceirizadoId] = useState('')
  const [turmaId, setTurmaId] = useState('')
  const [quantidadePessoas, setQuantidadePessoas] = useState('')

  const [lista, setLista] = useState([])
  const [totalCusto, setTotalCusto] = useState(0)

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  useEffect(() => {
    carregarDados()
  }, [])

  async function carregarDados() {
    try {
      const [resFunc, resTerc, resTurma] = await Promise.all([
        listarFuncionarios(),
        listarTerceirizados(),
        listarTurmas()
      ])

      // 🔥 GARANTE ARRAY SEMPRE
      setFuncionarios(
        resFunc.data?.data?.content ||
        resFunc.data?.data ||
        []
      )

      setTerceirizados(
        resTerc.data?.data?.content ||
        resTerc.data?.data ||
        []
      )

      setTurmas(
        resTurma.data?.data?.content ||
        resTurma.data?.data ||
        []
      )

    } catch (err) {
      console.error(err)
      setErro('Erro ao carregar dados')
    }
  }

  function calcularCusto(payload) {

    // FUNCIONÁRIO (placeholder)
    if (payload.tipo === 'FUNCIONARIO') {
      return 0
    }

    // TERCEIRIZADO (exemplo simples)
    if (payload.tipo === 'TERCEIRIZADO') {
      return (payload.quantidadePessoas || 0) * 100
    }

    // TURMA
    if (payload.tipo === 'TURMA') {
      const turma = turmas.find(t => t.id == payload.turmaId)
      if (!turma) return 0

      return (turma.valorDiaria || 0) * (turma.quantidadePessoas || 0)
    }

    return 0
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    if (tipo === 'FUNCIONARIO' && !funcionarioId) {
      setErro('Selecione o funcionário')
      return
    }

    if (tipo === 'TERCEIRIZADO' && !terceirizadoId) {
      setErro('Selecione o terceirizado')
      return
    }

    if (tipo === 'TURMA' && !turmaId) {
      setErro('Selecione a turma')
      return
    }

    const jaExiste = lista.some(i =>
      (tipo === 'FUNCIONARIO' && i.funcionarioId == funcionarioId) ||
      (tipo === 'TERCEIRIZADO' && i.terceirizadoId == terceirizadoId) ||
      (tipo === 'TURMA' && i.turmaId == turmaId)
    )

    if (jaExiste) {
      setErro('Item já adicionado')
      return
    }

    try {

      const payload = {
        tipo,
        funcionarioId: tipo === 'FUNCIONARIO' ? Number(funcionarioId) : null,
        terceirizadoId: tipo === 'TERCEIRIZADO' ? Number(terceirizadoId) : null,
        turmaId: tipo === 'TURMA' ? Number(turmaId) : null,
        quantidadePessoas: tipo !== 'TURMA'
          ? Number(quantidadePessoas || 0)
          : null
      }

      const res = await adicionarFuncionarioPlanejamento(id, payload)

      if (!res.data?.success) {
        setErro('Erro ao adicionar')
        return
      }

      const novoItem = {
        ...payload,
        funcionarioNome: funcionarios.find(f => f.id == funcionarioId)?.nome,
        terceirizadoNome: terceirizados.find(t => t.id == terceirizadoId)?.nome,
        turmaNome: turmas.find(t => t.id == turmaId)?.nome,
        custo: calcularCusto(payload)
      }

      const novaLista = [...lista, novoItem]

      const total = novaLista.reduce((t, i) => t + (i.custo || 0), 0)

      setLista(novaLista)
      setTotalCusto(total)

      setSucesso('Adicionado com sucesso')

      setFuncionarioId('')
      setTerceirizadoId('')
      setTurmaId('')
      setQuantidadePessoas('')

    } catch (err) {
      console.error(err)
      setErro('Erro ao salvar')
    }
  }

  return (
    <PageLayout
      title="Funcionários do Planejamento"
      showBack
      backTo="/safra-talhoes"
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <form className="form-container" onSubmit={handleSubmit}>

        <div>
          <label>Tipo</label>
          <select value={tipo} onChange={e => setTipo(e.target.value)}>
            <option value="FUNCIONARIO">Funcionário</option>
            <option value="TERCEIRIZADO">Terceirizado</option>
            <option value="TURMA">Turma</option>
          </select>
        </div>

        {tipo === 'FUNCIONARIO' && (
          <div>
            <label>Funcionário</label>
            <select value={funcionarioId} onChange={e => setFuncionarioId(e.target.value)}>
              <option value="">Selecione</option>
              {funcionarios.map(f => (
                <option key={f.id} value={f.id}>{f.nome}</option>
              ))}
            </select>
          </div>
        )}

        {tipo === 'TERCEIRIZADO' && (
          <div>
            <label>Terceirizado</label>
            <select value={terceirizadoId} onChange={e => setTerceirizadoId(e.target.value)}>
              <option value="">Selecione</option>
              {terceirizados.map(t => (
                <option key={t.id} value={t.id}>{t.nome}</option>
              ))}
            </select>
          </div>
        )}

        {tipo === 'TURMA' && (
          <div>
            <label>Turma</label>
            <select value={turmaId} onChange={e => setTurmaId(e.target.value)}>
              <option value="">Selecione</option>
              {turmas.map(t => (
                <option key={t.id} value={t.id}>{t.nome}</option>
              ))}
            </select>
          </div>
        )}

        {tipo !== 'TURMA' && (
          <FormInput
            label="Quantidade de Pessoas"
            type="number"
            value={quantidadePessoas}
            onChange={e => setQuantidadePessoas(e.target.value)}
          />
        )}

        <div className="form-actions">
          <button type="submit" className="add-btn">
            Adicionar
          </button>
        </div>

      </form>

      {lista.length > 0 && (
        <div className="card-list">
          {lista.map((i, index) => (
            <div key={index} className="card">
              {i.funcionarioNome ||
               i.terceirizadoNome ||
               i.turmaNome}
              {' '}| Qtde: {i.quantidadePessoas || '-'}
              {' '}| Custo: R$ {(i.custo || 0).toFixed(2)}
            </div>
          ))}
        </div>
      )}

      {lista.length > 0 && (
        <div style={{ marginTop: 20, fontWeight: 'bold' }}>
          Total Estimado: R$ {totalCusto.toFixed(2)}
        </div>
      )}

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Trash2, Pencil } from 'lucide-react'

import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import Alert from '../components/Alert'

import {
  adicionarInsumoPlanejamento,
  listarProdutos,
  listarInsumosPlanejamento,
  removerInsumoPlanejamento,
  obterResumoPlanejamento
} from '../api/api'

export default function PlanejamentoInsumos() {

  const { id } = useParams()
  const navigate = useNavigate()

  const [produtoId, setProdutoId] = useState('')
  const [dosePorHa, setDosePorHa] = useState('')
  const [valorUnitarioPrevisto, setValorUnitarioPrevisto] = useState('')

  const [produtos, setProdutos] = useState([])
  const [insumos, setInsumos] = useState([])
  const [resumo, setResumo] = useState(null)

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')

  useEffect(() => {
    if (!id) {
      setErro('ID do planejamento não encontrado')
      return
    }

    carregarTudo()
  }, [id])

  async function carregarTudo() {
    await Promise.all([
      carregarProdutos(),
      carregarInsumos(),
      carregarResumo()
    ])
  }

  async function carregarProdutos() {
    const res = await listarProdutos()
    setProdutos(res.data?.data?.content || res.data?.data || [])
  }

  async function carregarInsumos() {
    if (!id) return
    const res = await listarInsumosPlanejamento(id)
    setInsumos(res.data?.data || [])
  }

  async function carregarResumo() {
    if (!id) return
    const res = await obterResumoPlanejamento(id)
    setResumo(res.data?.data)
  }

  function editarInsumo(item) {
    setProdutoId(String(item.produtoId || item.produto?.id))
    setDosePorHa(item.dosePorHa)
    setValorUnitarioPrevisto(item.valorUnitarioPrevisto)
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    if (!id) {
      setErro('ID do planejamento inválido')
      return
    }

    if (resumo?.possuiOs) {
      setErro('Planejamento já possui OS gerada')
      return
    }

    if (!produtoId) {
      setErro('Selecione o produto')
      return
    }

    if (!dosePorHa || !valorUnitarioPrevisto) {
      setErro('Preencha todos os campos')
      return
    }

    const jaExiste = insumos.some(i =>
      String(i.produtoId || i.produto?.id) === produtoId
    )

    if (jaExiste) {
      setErro('Produto já adicionado')
      return
    }

    try {
      const res = await adicionarInsumoPlanejamento(id, {
        produtoId: Number(produtoId),
        dosePorHa: Number(dosePorHa),
        valorUnitarioPrevisto: Number(valorUnitarioPrevisto)
      })

      if (!res.ok || res.data?.success === false) {
        setErro(res.data?.message || 'Erro ao adicionar insumo')
        return
      }

      setSucesso('Insumo adicionado')

      setProdutoId('')
      setDosePorHa('')
      setValorUnitarioPrevisto('')

      await carregarInsumos()
      await carregarResumo()

    } catch (err) {
      console.error(err)
      setErro('Erro ao adicionar insumo')
    }
  }

  async function remover(itemId) {
    if (!id) return

    if (resumo?.possuiOs) {
      setErro('Planejamento já possui OS gerada')
      return
    }

    try {
      await removerInsumoPlanejamento(id, itemId)
      await carregarInsumos()
      await carregarResumo()
    } catch (err) {
      console.error(err)
      setErro('Erro ao remover')
    }
  }

  // 🔥 TOTAL CUSTO
  const totalInsumos = insumos.reduce((total, i) => {
    const custo =
      resumo?.areaTotal
        ? (i.dosePorHa * i.valorUnitarioPrevisto * resumo.areaTotal)
        : 0
    return total + custo
  }, 0)

  // 🔥 TOTAL DOSE
  const totalDose = insumos.reduce((total, i) => {
    return total + Number(i.dosePorHa || 0)
  }, 0)

  // 🔥 TOTAL VALOR UNITÁRIO
  const totalValorUnitario = insumos.reduce((total, i) => {
    return total + Number(i.valorUnitarioPrevisto || 0)
  }, 0)

  return (
    <PageLayout
      title="Insumos do Planejamento"
      showBack
      backTo="/safra-talhoes"
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      {resumo?.possuiOs && (
        <Alert
          type="warning"
          message="Planejamento já possui OS gerada. Edição bloqueada."
        />
      )}

      <form
        className="form-container"
        onSubmit={handleSubmit}
        style={{ opacity: resumo?.possuiOs ? 0.5 : 1 }}
      >

        <div>
          <label>Produto</label>
          <select
            value={produtoId}
            onChange={e => {
              const idSelecionado = e.target.value
              setProdutoId(idSelecionado)

              const produto = produtos.find(p => String(p.id) === idSelecionado)

              if (produto?.vlrUnitario !== undefined) {
                setValorUnitarioPrevisto(produto.vlrUnitario)
              }
            }}
            disabled={resumo?.possuiOs}
          >
            <option value="">Selecione</option>
            {produtos.map(p => (
              <option key={p.id} value={String(p.id)}>
                {p.nome}
              </option>
            ))}
          </select>
        </div>

        <FormInput
          label="Dose por Hectare"
          type="number"
          value={dosePorHa}
          onChange={e => setDosePorHa(e.target.value)}
          disabled={resumo?.possuiOs}
        />

        <FormInput
          label="Valor Unitário"
          type="number"
          value={valorUnitarioPrevisto}
          onChange={e => setValorUnitarioPrevisto(e.target.value)}
          disabled={resumo?.possuiOs}
        />

        <div className="form-actions">
          <button
            type="submit"
            className="add-btn"
            disabled={resumo?.possuiOs}
          >
            Adicionar
          </button>
        </div>

      </form>

      {insumos.length > 0 && (
        <div style={{ marginTop: 20 }}>

          <table className="table-insumos compact">
            <thead>
              <tr>
                <th>Produto</th>
                <th>Dose/Ha</th>
                <th>Valor Unit.</th>
                <th>Custo</th>
                <th style={{ width: 100 }}>Ações</th>
              </tr>
            </thead>

            <tbody>
              {insumos.map(i => {

                const custo =
                  resumo?.areaTotal
                    ? (i.dosePorHa * i.valorUnitarioPrevisto * resumo.areaTotal)
                    : 0

                return (
                  <tr key={i.id}>

                    <td className="col-produto">
                      {i.produtoNome || `Produto ${i.produtoId}`}
                    </td>

                    <td>{i.dosePorHa}</td>

                    <td>
                      R$ {Number(i.valorUnitarioPrevisto).toFixed(2)}
                    </td>

                    <td className="col-custo">
                      R$ {custo.toFixed(2)}
                    </td>

                    <td className="acoes">
                      <button
                        className="icon-button edit"
                        onClick={() => editarInsumo(i)}
                        title="Editar"
                      >
                        <Pencil size={16} />
                      </button>

                      <button
                        className="icon-button danger"
                        onClick={() => remover(i.id)}
                        title="Remover"
                      >
                        <Trash2 size={16} />
                      </button>
                    </td>

                  </tr>
                )
              })}
            </tbody>

            <tfoot>
              <tr>
                <td style={{ fontWeight: 600 }}>Totais:</td>

                <td style={{ fontWeight: 600 }}>
                  {totalDose.toFixed(2)}
                </td>

                <td style={{ fontWeight: 600 }}>
                  R$ {totalValorUnitario.toFixed(2)}
                </td>

                <td className="col-custo">
                  R$ {totalInsumos.toFixed(2)}
                </td>

                <td></td>
              </tr>
            </tfoot>

          </table>

        </div>
      )}

      <div style={{ marginTop: 20 }}>
        <button
          className="add-btn"
          onClick={() => navigate(`/planejamento/${id}/maquinas`)}
        >
          Avançar para Máquinas →
        </button>
      </div>

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useAuth } from '../auth/AuthContext'
import { Trash2, Pencil } from 'lucide-react'

import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import Alert from '../components/Alert'

import {
  adicionarMaquinaPlanejamento,
  listarMaquinas,
  listarMaquinasPlanejamento,
  removerMaquinaPlanejamento,
  obterResumoPlanejamento
} from '../api/api'

export default function PlanejamentoMaquinas() {

  const { id } = useParams()
  const navigate = useNavigate()
  const { user } = useAuth()

  const podeEditar = user?.perfilId === 2

  const [maquinaId, setMaquinaId] = useState('')
  const [horasPrevistas, setHorasPrevistas] = useState('')
  const [custoHora, setCustoHora] = useState('')

  const [maquinas, setMaquinas] = useState([])
  const [itens, setItens] = useState([])
  const [resumo, setResumo] = useState(null)

  const [erro, setErro] = useState('')
  const [sucesso, setSucesso] = useState('')



  async function carregarTudo() {
    await Promise.all([
      carregarMaquinas(),
      carregarItens(),
      carregarResumo()
    ])
  }

  async function carregarMaquinas() {
    const res = await listarMaquinas()
    setMaquinas(res.data?.data?.content || res.data?.data || [])
  }

  async function carregarItens() {
    const res = await listarMaquinasPlanejamento(id)
    setItens(res.data?.data || [])
  }

  async function carregarResumo() {
    const res = await obterResumoPlanejamento(id)
    setResumo(res.data?.data)
  }

  useEffect(() => {
    carregarTudo()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id])

  function editar(item) {
    setMaquinaId(String(item.maquinaId || item.maquina?.id))
    setHorasPrevistas(item.horasPrevistas)
    setCustoHora(item.custoHora)
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setErro('')
    setSucesso('')

    if (!podeEditar) {
      setErro('Sem permissão')
      return
    }

    if (!maquinaId || !horasPrevistas) {
      setErro('Preencha os campos')
      return
    }

    try {
      await adicionarMaquinaPlanejamento(id, {
        maquinaId: Number(maquinaId),
        horasPrevistas: Number(horasPrevistas),
        custoHora: custoHora ? Number(custoHora) : null // 🔥 backend resolve fallback
      })

      setSucesso('Máquina adicionada')

      setMaquinaId('')
      setHorasPrevistas('')
      setCustoHora('')

      await carregarItens()
      await carregarResumo()

    } catch (err) {
      console.error(err)
      setErro('Erro ao salvar')
    }
  }

  async function remover(itemId) {
    if (!podeEditar) return

    try {
      await removerMaquinaPlanejamento(id, itemId)
      await carregarItens()
      await carregarResumo()
    } catch (err) {
      console.error(err)
      setErro('Erro ao remover')
    }
  }

  // 🔥 TOTAL HORAS
  const totalHoras = itens.reduce((t, i) => t + Number(i.horasPrevistas || 0), 0)

  // 🔥 TOTAL CUSTO
  const totalCusto = itens.reduce((t, i) => {
    const custo = i.horasPrevistas * i.custoHora
    return t + custo
  }, 0)

  return (
    <PageLayout
      title="Máquinas do Planejamento"
      showBack
      backTo={`/planejamento/${id}/insumos`}
    >

      {erro && <Alert type="error" message={erro} />}
      {sucesso && <Alert type="success" message={sucesso} />}

      <form className="form-container" onSubmit={handleSubmit}>

        <div>
          <label>Máquina</label>
          <select
            value={maquinaId}
            onChange={e => {
              const idSelecionado = e.target.value
              setMaquinaId(idSelecionado)

              const maq = maquinas.find(m => String(m.id) === idSelecionado)

              if (maq?.custoHora) {
                setCustoHora(maq.custoHora) // 🔥 AUTO
              }
            }}
            disabled={!podeEditar}
          >
            <option value="">Selecione</option>
            {maquinas.map(m => (
              <option key={m.id} value={String(m.id)}>
                {m.nome}
              </option>
            ))}
          </select>
        </div>

        <FormInput
          label="Horas Previstas"
          type="number"
          value={horasPrevistas}
          onChange={e => setHorasPrevistas(e.target.value)}
          disabled={!podeEditar}
        />

        <FormInput
          label="Custo por Hora (opcional)"
          type="number"
          value={custoHora}
          onChange={e => setCustoHora(e.target.value)}
          disabled={!podeEditar}
        />

        {podeEditar && (
          <div className="form-actions">
            <button type="submit" className="add-btn">
              Adicionar
            </button>
          </div>
        )}

      </form>

      {itens.length > 0 && (
        <div style={{ marginTop: 20 }}>

          <table className="table-insumos compact">
            <thead>
              <tr>
                <th>Máquina</th>
                <th>Horas</th>
                <th>Custo/Hora</th>
                <th>Custo</th>
                <th style={{ width: 100 }}>Ações</th>
              </tr>
            </thead>

            <tbody>
              {itens.map(i => {

                const custo = i.horasPrevistas * i.custoHora

                return (
                  <tr key={i.id}>

                    <td>{i.maquinaNome || i.maquinaId}</td>

                    <td>{i.horasPrevistas}</td>

                    <td>R$ {Number(i.custoHora).toFixed(2)}</td>

                    <td className="col-custo">
                      R$ {custo.toFixed(2)}
                    </td>

                    <td className="acoes">

                      <button
                        className="icon-button edit"
                        onClick={() => editar(i)}
                        title="Editar"
                      >
                        <Pencil size={16} />
                      </button>

                      <button
                        className="icon-button danger"
                        onClick={() => remover(i.id)}
                        title="Remover"
                      >
                        <Trash2 size={16} />
                      </button>

                    </td>

                  </tr>
                )
              })}
            </tbody>

            <tfoot>
              <tr>
                <td style={{ fontWeight: 600 }}>Totais:</td>

                <td style={{ fontWeight: 600 }}>
                  {totalHoras.toFixed(2)}
                </td>

                <td></td>

                <td className="col-custo">
                  R$ {totalCusto.toFixed(2)}
                </td>

                <td></td>
              </tr>
            </tfoot>

          </table>

        </div>
      )}

      <div style={{ marginTop: 20 }}>
        <button
          className="add-btn"
          onClick={() => navigate(`/planejamento/${id}/funcionarios`)}
        >
          Avançar para Mão de Obra →
        </button>
      </div>

    </PageLayout>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import '../styles/pages.css'
import '../styles/form.css'
import Alert from '../components/Alert'
import PageLayout from '../components/PageLayout'
import FormInput from '../components/FormInput'
import {
    verificarCpf,
    criarProprietario,
    buscarProprietario,
    atualizarProprietario
} from '../api/api'

export default function ProprietarioForm() {
    const navigate = useNavigate()
    const { id } = useParams()
    const modoEdicao = !!id

    const [cpf, setCpf] = useState('')
    const [nome, setNome] = useState('')
    const [email, setEmail] = useState('')
    const [celular, setCelular] = useState('')
    const [endereco, setEndereco] = useState('')
    const [bairro, setBairro] = useState('')
    const [cidade, setCidade] = useState('')
    const [estado, setEstado] = useState('')

    const [cpfVerificado, setCpfVerificado] = useState(modoEdicao)
    function formatarCpf(valor) {
        valor = valor.replace(/\D/g, '')
        valor = valor.replace(/^(\d{3})(\d)/, '$1.$2')
        valor = valor.replace(/^(\d{3})\.(\d{3})(\d)/, '$1.$2.$3')
        valor = valor.replace(/\.(\d{3})(\d)/, '.$1-$2')
        return valor.slice(0, 14)
    }

    useEffect(() => {
        async function carregarProprietario() {
            try {
                const response = await buscarProprietario(id)
                if (!response.ok || !response.data?.data) {
                    setErro('Erro ao carregar proprietário')
                    return
                }

                const p = response.data.data
                setCpf(formatarCpf(p.cpf || ''))
                setNome(p.nome || '')
                setEmail(p.email || '')
                setCelular(p.celular || '')
                setEndereco(p.endereco || '')
                setBairro(p.bairro || '')
                setCidade(p.cidade || '')
                setEstado(p.estado || '')
            } catch (err) {
                console.error(err)
                setErro('Erro ao carregar proprietário')
            }
        }

        if (modoEdicao) carregarProprietario()
    }, [id, modoEdicao])

    function limparCpf(valor) {
        return valor.replace(/\D/g, '')
    }

    function handleCpfChange(e) {
        const valor = formatarCpf(e.target.value)
        setCpf(valor)
        setCpfVerificado(false)
        setErro('')
        setSucesso('')
    }

    async function validarCpfNoBackend(valorCpf) {
        setErro('')
        setSucesso('')
        const cpfLimpo = limparCpf(valorCpf)

        if (cpfLimpo.length !== 11) {
            setErro('Informe um CPF válido')
            setCpfVerificado(false)
            return false
        }

        try {
            const response = await verificarCpf(cpfLimpo)

            if (!response.data?.success) {
                setErro(response.data?.message || 'Erro ao verificar CPF')
                setCpfVerificado(false)
                return false
            }

            if (response.data.data === false) {
                setErro('CPF já cadastrado')
                setCpfVerificado(false)
                return false
            }

            setCpfVerificado(true)
            return true
        } catch (error) {
            console.error(error)
            setErro('Erro ao verificar CPF')
            setCpfVerificado(false)
            return false
        }
    }

    async function handleSubmit(e) {
        e.preventDefault()
        setErro('')
        setSucesso('')

        const cpfLimpo = limparCpf(cpf)

        if (!modoEdicao) {
            const valido = await validarCpfNoBackend(cpf)
            if (!valido) return
        }

        if (!nome) {
            setErro('Informe o nome do proprietário')
            return
        }

        if (!email) {
            setErro('Informe o e-mail')
            return
        }

        try {
            let response

            if (modoEdicao) {
                response = await atualizarProprietario(id, {
                    cpf: cpfLimpo,
                    nome,
                    email,
                    celular,
                    endereco,
                    bairro,
                    cidade,
                    estado
                })
            } else {
                response = await criarProprietario({
                    cpf: cpfLimpo,
                    nome,
                    email,
                    celular,
                    endereco,
                    bairro,
                    cidade,
                    estado
                })
            }

            if (!response.ok || !response.data?.success) {
                setErro(response.data?.message || 'Erro ao salvar proprietário')
                return
            }

            setSucesso(
                modoEdicao
                    ? 'Proprietário atualizado com sucesso'
                    : 'Proprietário cadastrado com sucesso'
            )

            setTimeout(() => navigate('/proprietarios'), 1200)
        } catch (error) {
            console.error(error)
            setErro('Erro ao salvar proprietário')
        }
    }

    return (
        <PageLayout
            title={modoEdicao ? 'Editar Proprietário' : 'Novo Proprietário'}
            showBack
            backTo="/proprietarios"
        >
            {erro && <Alert type="error" message={erro} />}
            {sucesso && <Alert type="success" message={sucesso} />}

            <form className="form-container" onSubmit={handleSubmit}>
                {!modoEdicao && (
                    <FormInput
                        label="CPF"
                        value={cpf}
                        onChange={handleCpfChange}
                        onBlur={() => validarCpfNoBackend(cpf)}
                        onKeyDown={async (e) => {
                            if (e.key === 'Enter') {
                                e.preventDefault()
                                await validarCpfNoBackend(cpf)
                            }
                        }}
                        placeholder="000.000.000-00"
                        style={{ maxWidth: '200px' }}
                    />
                )}

                {(cpfVerificado || modoEdicao) && (
                    <>
                        <FormInput
                            label="Nome"
                            value={nome}
                            onChange={e => setNome(e.target.value)}
                            uppercase
                            required
                        />

                        {/* EMAIL 3 / CELULAR 1 */}
                        <div className="form-grid-4">
                            <div style={{ gridColumn: 'span 3' }}>
                                <FormInput
                                    label="E-mail"
                                    type="email"
                                    value={email}
                                    onChange={e => setEmail(e.target.value)}
                                    required
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Celular"
                                    value={celular}
                                    onChange={e => setCelular(e.target.value)}
                                />
                            </div>
                        </div>

                        <FormInput
                            label="Endereço"
                            value={endereco}
                            onChange={e => setEndereco(e.target.value)}
                            uppercase
                        />

                        {/* BAIRRO 2 / CIDADE 2 / ESTADO 1 */}
                        <div className="form-grid-5">
                            <div style={{ gridColumn: 'span 2' }}>
                                <FormInput
                                    label="Bairro"
                                    value={bairro}
                                    onChange={e => setBairro(e.target.value)}
                                    uppercase
                                />
                            </div>
                            <div style={{ gridColumn: 'span 2' }}>
                                <FormInput
                                    label="Cidade"
                                    value={cidade}
                                    onChange={e => setCidade(e.target.value)}
                                    uppercase
                                />
                            </div>
                            <div style={{ gridColumn: 'span 1' }}>
                                <FormInput
                                    label="Estado"
                                    value={estado}
                                    onChange={e => setEstado(e.target.value)}
                                    maxLength={2}
                                    placeholder="UF"
                                    uppercase
                                />
                            </div>
                        </div>

                        <div className="form-actions">
                            <button type="submit" className="add-btn">
                                {modoEdicao ? 'Salvar alterações' : 'Salvar proprietário'}
                            </button>
                        </div>
                    </>
                )}
            </form>
        </PageLayout>
    )
}
